import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import { db8 } from "@/lib/db.prisma8";
import { logj } from "@/lib/log/logj";
import { buildUniversalContext } from "@/lib/log/build-universal-context";

export async function GET(req: NextRequest) {
  const start = performance.now();
  const built = await buildUniversalContext(req, "GITHUB_ACTIVITY");
  let eventIndex = 0;

  // --- Request Start ---------------------------------------------------------
  await logj({
    domain: "GITHUB_ACTIVITY",
    level: "info",
    message: "GitHub activity request started",
    file: "app/api/activity/github/route.ts",
    line: 13,
    meta: { built: { ...built, eventIndex: ++eventIndex } },
  });

  try {
    // --- Prisma Query Diagnostics -------------------------------------------
    await logj({
      domain: "GITHUB_ACTIVITY",
      level: "debug",
      message: "Querying Prisma for recent GitHub events",
      file: "app/api/activity/github/route.ts",
      line: 24,
      meta: { built: { ...built, eventIndex: ++eventIndex } },
    });

    const events = await db8.orm.public.GithubEvent.orderBy((githubEvent) =>
      githubEvent.updatedAt.desc(),
    )
      .limit(50)
      .all();

    await logj({
      domain: "GITHUB_ACTIVITY",
      level: "info",
      message: `Prisma returned ${events.length} events`,
      file: "app/api/activity/github/route.ts",
      line: 39,
      payload: { count: events.length },
      meta: { built: { ...built, eventIndex: ++eventIndex } },
    });

    // --- Normalization -------------------------------------------------------
    const normalized = events.map((e) => ({
      id: e.id,
      name: e._type,
      repo: e.repo,
      status: e.status,
      conclusion: e.conclusion,
      event: e._type,
      actor: e.actor,
      commitMessage: e.commitMessage,
      commitSha: e.commitSha,
      url: e.url,
      createdAt: e.createdAt,
      updatedAt: e.updatedAt,
      source: "github",
    }));

    await logj({
      domain: "GITHUB_ACTIVITY",
      level: "debug",
      message: "Normalized GitHub events",
      file: "app/api/activity/github/route.ts",
      line: 66,
      payload: { sample: normalized[0] ?? null, count: normalized.length },
      meta: { built: { ...built, eventIndex: ++eventIndex } },
    });

    // --- Deduplication -------------------------------------------------------
    const bySha = new Map<string, any>();

    for (const item of normalized) {
      const sha = item.commitSha ?? item.id;

      if (!bySha.has(sha)) {
        bySha.set(sha, item);
        continue;
      }

      const existing = bySha.get(sha);
      const isSuccess = (x: any) => x.conclusion === "success";

      if (isSuccess(item) && !isSuccess(existing)) {
        bySha.set(sha, item);
        continue;
      }

      if (item.updatedAt.toString() > existing.updatedAt.toString()) {
        bySha.set(sha, item);
      }
    }

    const activity = Array.from(bySha.values());

    await logj({
      domain: "GITHUB_ACTIVITY",
      level: "info",
      message: "Deduplication complete",
      file: "app/api/activity/github/route.ts",
      line: 113,
      payload: {
        before: normalized.length,
        after: activity.length,
      },
      meta: { built: { ...built, eventIndex: ++eventIndex } },
    });

    // --- Request End ---------------------------------------------------------
    const duration = performance.now() - start;

    await logj({
      domain: "GITHUB_ACTIVITY",
      level: "info",
      message: `GitHub activity request completed in ${duration.toFixed(2)}ms`,
      file: "app/api/activity/github/route.ts",
      line: 129,
      meta: { built: { ...built, eventIndex: ++eventIndex } },
    });

    return NextResponse.json({ ok: true, activity });
  } catch (err: unknown) {
    const duration = performance.now() - start;
    const message = err instanceof Error ? err.message : String(err);

    // --- Error Logging -------------------------------------------------------
    await logj({
      domain: "GITHUB_ACTIVITY",
      level: "error",
      message: `GitHub activity failed: ${message}`,
      file: "app/api/activity/github/route.ts",
      line: 144,
      payload: {
        error: message,
        stack: err instanceof Error ? err.stack : null,
      },
      meta: { built: { ...built, eventIndex: ++eventIndex, duration } },
    });

    return NextResponse.json({ ok: false, error: message }, { status: 500 });
  }
}

export async function PUT() {
  return NextResponse.json({ ok: true, note: "PUT no longer needed" });
}

export async function DELETE() {
  return NextResponse.json({ ok: true, note: "DELETE no longer needed" });
}

import { NextResponse } from "next/server";

export async function GET() {
  const token = process.env.VERCEL_TOKEN;
  const projectId = process.env.VERCEL_PROJECT_ID;
  console.log("Started Vercel");
  const res = await fetch(
    `https://api.vercel.com/v6/deployments?projectId=${projectId}&limit=5`,
    {
      headers: {
        Authorization: `Bearer ${token}`,
      },
      cache: "no-store",
    },
  );

  if (!res.ok) {
    return NextResponse.json(
      { error: "Failed to fetch Vercel deployments" },
      { status: 500 },
    );
  }

  const { deployments } = await res.json();

  const mapped = deployments.map((d: any) => ({
    id: d.uid,
    url: d.url,
    state: d.state,
    createdAt: d.created,
    creator: d.meta?.githubCommitAuthorName,
    commitMessage: d.meta?.githubCommitMessage,
    commitSha: d.meta?.githubCommitSha,
  }));

  return NextResponse.json(mapped);
}

import { describe, it, expect, vi, beforeEach } from "vitest";

vi.mock("@/lib/db.prisma8", () => {
  const mockDb8 = {
    orm: {
      public: {
        RuntimeConfig: {
          orderBy: vi.fn().mockReturnThis(),
          all: vi.fn().mockResolvedValue([]),
        },
      },
    },
  };

  return { db8: mockDb8 };
});

const { db8 } = await import("@/lib/db.prisma8");
const mockedDb8 = vi.mocked(db8, true);

beforeEach(() => {
  vi.clearAllMocks();

  mockedDb8.orm.public.RuntimeConfig.orderBy.mockReturnValue(
    mockedDb8.orm.public.RuntimeConfig,
  );
});

describe("GET /api/admin/runtime", () => {
  it("returns an empty list when no configs exist", async () => {
    mockedDb8.orm.public.RuntimeConfig.all.mockResolvedValue([]);

    const { GET } = await import("../route");
    const res = await GET();
    const json = await res.json();

    expect(res.status).toBe(200);
    expect(json.configs).toEqual([]);
  });

  it("returns configs mapped to key/value and requests DB ordering", async () => {
    const mocked = [
      {
        key: "z.alpha",
        value: "3",
        createdAt: new Date(),
        updatedAt: new Date(),
      },
      {
        key: "a.beta",
        value: "1",
        createdAt: new Date(),
        updatedAt: new Date(),
      },
      {
        key: "m.gamma",
        value: "2",
        createdAt: new Date(),
        updatedAt: new Date(),
      },
    ] as any;

    mockedDb8.orm.public.RuntimeConfig.all.mockResolvedValue(mocked);

    const { GET } = await import("../route");
    const res = await GET();
    const json = await res.json();

    expect(res.status).toBe(200);

    expect(mockedDb8.orm.public.RuntimeConfig.orderBy).toHaveBeenCalled();

    expect(json.configs).toEqual(
      mocked.map((c: any) => ({ key: c.key, value: c.value })),
    );
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { GET } from "../route";

vi.mock("@/lib/axiom/query", () => ({
  queryAxiom: vi.fn(),
}));

vi.mock("@/lib/log/logj", () => ({
  logj: vi.fn().mockResolvedValue(undefined),
}));

const { queryAxiom } = await import("@/lib/axiom/query");

describe("GET /api/config/read", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("returns latest flight and weather rows with new stats shape", async () => {
    // First call → Flight rows
    vi.mocked(queryAxiom).mockResolvedValueOnce([
      {
        id: "f1",
        reason: "Flight",
        message: "flight",
        _time: "2026-03-16T00:00:00Z",
      } as any,
    ]);

    // Second call → Weather rows
    vi.mocked(queryAxiom).mockResolvedValueOnce([
      {
        id: "w1",
        reason: "Weather",
        message: "weather",
        _time: "2026-03-16T00:00:00Z",
      } as any,
    ]);

    const res = await GET();
    expect(res.status).toBe(200);

    const json = await res.json();

    expect(json.flight).toEqual({
      id: "f1",
      reason: "Flight",
      message: "flight",
      _time: "2026-03-16T00:00:00Z",
    });

    expect(json.weather).toEqual({
      id: "w1",
      reason: "Weather",
      message: "weather",
      _time: "2026-03-16T00:00:00Z",
    });

    // New stats shape
    expect(json.stats).toEqual({
      total: 2,
      flights: 1,
      weather: 1,
      lastUpdated: "2026-03-16T00:00:00Z",
    });

    // Only 2 calls now (Flight + Weather)
    expect(queryAxiom).toHaveBeenCalledTimes(2);
  });

  it("returns 500 on query failure", async () => {
    vi.mocked(queryAxiom).mockRejectedValueOnce(new Error("fail"));

    const res = await GET();
    expect(res.status).toBe(500);

    const json = await res.json();
    expect(json.error).toContain("fail");
  });
});

// app/api/cron/astronomy/route.ts
import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import { db8 } from "@/lib/db.prisma8";
import { logj } from "@/lib/log/logj";
import { createId } from "@paralleldrive/cuid2";
import { staticUniversalContext } from "@/lib/log/buildj";
import { timestampString } from "@/lib/timestampString";
import { addDays, format } from "date-fns";
import { buildAstronomySnapshot } from "@/lib/buildAstronomySnapshot";
import { getConfig, setConfig } from "@/lib/runtime/config";

export const runtime = "nodejs";

const varchar10 = (value: string) =>
  value as string & { readonly __varcharLength: 10 };

// Force a date to local midnight
function atLocalMidnight(d: Date) {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}
async function cleanupOldLogs(days: number, built: any) {
  const cutoff = new Date(Date.now() - days * 24 * 60 * 60 * 1000);
  let jei = 0;
  // Count before

  const { total: beforeCount } = await db8.orm.public.Log.aggregate((agg) => ({
    total: agg.count(),
  }));

  const deleteCount = await db8.orm.public.Log.where((log) =>
    log.createdAt.lt(timestampString(cutoff.toISOString())),
  ).deleteAndCount();

  const { total: afterCount } = await db8.orm.public.Log.aggregate((agg) => ({
    total: agg.count(),
  }));

  // Log the cleanup
  await logj({
    domain: "logs",
    level: "info",
    message: `Log cleanup completed`,
    file: "app/api/cron/astronomy/route.ts",
    line: 40,
    payload: {
      beforeCount,
      deleted: deleteCount,
      afterCount,
      cutoff: cutoff.toISOString(),
    },
    meta: { built: { ...built, eventIndex: ++jei } },
  });

  return deleteCount;
}
async function cleanupEphem(days: number, built: any) {
  const cutoff = new Date(Date.now() - days * 24 * 60 * 60 * 1000);
  let jei = 1;
  // Count before

  const { total: beforeCount } = await db8.orm.public.EphemerisDebug.aggregate(
    (agg) => ({
      total: agg.count(),
    }),
  );

  const deleteCount = await db8.orm.public.EphemerisDebug.where((log) =>
    log.createdAt.lt(timestampString(cutoff.toISOString())),
  ).deleteAndCount();

  const { total: afterCount } = await db8.orm.public.EphemerisDebug.aggregate(
    (agg) => ({
      total: agg.count(),
    }),
  );
  // Log the cleanup
  await logj({
    domain: "ephemeris",
    level: "info",
    message: `Ephemeris cleanup completed`,
    file: "app/api/cron/astronomy/route.ts",
    line: 78,
    payload: {
      beforeCount,
      deleted: deleteCount,
      afterCount,
      cutoff: cutoff.toISOString(),
    },
    meta: { built: { ...built, eventIndex: ++jei } },
  });

  return deleteCount;
}
export async function GET(req: NextRequest) {
  const start = Date.now();
  const built = staticUniversalContext("ASTRONOMY");
  let jei = 1;
  const locations = await db8.orm.public.Location.all();

  const durationMs = Date.now() - start;

  for (const location of locations) {
    await logj({
      domain: "ephemeris",
      level: "info",
      message: `Astronomy cron location started for ${location.name}`,
      file: "app/api/cron/astronomy/route.ts",
      line: 104,
      payload: {
        name: location.name,
      },
      meta: { built: { ...built, eventIndex: ++jei } },
    });

    const base = atLocalMidnight(new Date());

    for (let i = 0; i < 7; i++) {
      const targetDate = addDays(base, i);
      const dateString = varchar10(format(targetDate, "yyyy-MM-dd"));

      await logj({
        domain: "ephemeris",
        level: "info",
        message: `Astronomy cron day started for ${location.name} count: ${i + 1}`,
        file: "app/api/cron/astronomy/route.ts",
        line: 122,
        payload: {
          count: i,
        },
        meta: { built: { ...built, eventIndex: ++jei } },
      });

      const snapshot = await buildAstronomySnapshot(location, targetDate);

      const row = {
        ...snapshot,
        locationId: location.id,
        dateString,
      };

      const existing = await db8.orm.public.AstronomySnapshot.where(
        (snapshot) => snapshot.locationId.eq(location.id),
      )
        .where((snapshot) => snapshot.dateString.eq(dateString))
        .first();

      if (existing) {
        await db8.orm.public.AstronomySnapshot.where({
          id: existing.id,
        }).update(row);
      } else {
        await db8.orm.public.AstronomySnapshot.create({
          ...row,
          id: createId(),
        });
      }

      await logj({
        domain: "ephemeris",
        level: "info",
        message: `Astronomy cron location upsert for ${location.name} completed`,
        file: "app/api/cron/astronomy/route.ts",
        line: 159,
        payload: {
          duration: durationMs,
        },
        meta: { built: { ...built, eventIndex: ++jei } },
      });
      const logDays = await getConfig("logDays", "61");
      const logDaysNum = logDays?.toString() ?? "61";
      const cleanupDays = Number.isNaN(logDaysNum)
        ? 61
        : parseInt(logDaysNum, 10);
      const deleted = await cleanupOldLogs(cleanupDays, built);

      await logj({
        domain: "ephemeris",
        level: "info",
        message: `Astronomy cron completed deleted ${deleted} logs`,
        file: "app/api/cron/astronomy/route.ts",
        line: 177,
        payload: {
          durationMs,
          logDays: logDays,
          logDaysNum: logDaysNum,
          cleanupDays: cleanupDays,
          logsDeleted: deleted,
        },
        meta: { built: { ...built, eventIndex: ++jei } },
      });
      return NextResponse.json({ ok: true, durationMs });
    }
  }
}

import { NextResponse } from "next/server";

const owner = "jonathan-kraus";
const repo = "my-new-app";

export async function GET() {
  const token = process.env.GITHUB_TOKEN;

  const deploymentsRes = await fetch(
    `https://api.github.com/repos/${owner}/${repo}/deployments?per_page=5`,
    {
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: "application/vnd.github+json",
      },
      cache: "no-store",
    },
  );

  if (!deploymentsRes.ok) {
    return NextResponse.json(
      { error: "Failed to fetch deployments" },
      { status: 500 },
    );
  }

  const deployments = await deploymentsRes.json();

  // Fetch statuses for each deployment
  const enriched = await Promise.all(
    deployments.map(async (d: any) => {
      const statusRes = await fetch(d.statuses_url, {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/vnd.github+json",
        },
      });

      const statuses = await statusRes.json();
      const latest = statuses[0];

      return {
        id: d.id,
        sha: d.sha,
        ref: d.ref,
        environment: d.environment,
        created_at: d.created_at,
        creator: d.creator?.login,
        status: latest?.state ?? "unknown",
        log_url: latest?.log_url ?? null,
      };
    }),
  );

  return NextResponse.json(enriched);
}

import { NextResponse } from "next/server";

export async function GET() {
  const env = {
    nodeEnv: process.env.NODE_ENV ?? null,

    nextPublicAppUrl: process.env.NEXT_PUBLIC_APP_URL ?? null,
    vercel: !!process.env.VERCEL,
    databaseUrlPresent: !!process.env.DATABASE_URL,
    prismaClientPresent: await (async () => {
      try {
        // Check the Prisma 8 runtime without opening a database connection.

        const pkg = await import("@prisma/orm-postgres/runtime");
        return typeof pkg.default === "function";
      } catch (e) {
        return false;
      }
    })(),
    githubClientIdPresent: !!(
      process.env.GITHUB_CLIENT_ID ||
      process.env.GITHUB_ID ||
      process.env.AUTH_GITHUB_ID
    ),
    githubClientSecretPresent: !!(
      process.env.GITHUB_CLIENT_SECRET ||
      process.env.GITHUB_SECRET ||
      process.env.AUTH_GITHUB_SECRET
    ),

    nextAuthPresent: !!(
      process.env.NEXTAUTH_URL || process.env.NEXTAUTH_SECRET
    ),
  };

  return NextResponse.json({ env });
}

// app/api/environment/route.ts
import { NextResponse } from "next/server";
import { db8 } from "@/lib/db.prisma8";
import { logj } from "@/lib/log/logj";
import { buildUniversalContext } from "@/lib/log/build-universal-context";
import { getPostgresVersion } from "@/app/db/PgVersion";
import { getFullPackageData } from "@/lib/version/get-full-package-data";

export async function GET(req: Request) {
  const built = await buildUniversalContext(req, "environment");
  let jei = 0;

  await logj({
    domain: "environment",
    level: "info",
    message: "** Environment -- Starting Status Check **",
    file: "app/api/environment/route.ts",
    line: 13,
    payload: { some: "data" },
    meta: { built: { ...built, eventIndex: ++jei } },
  });

  try {
    //
    // 1. Get Postgres version directly from Neon (via Prisma)
    //
    const postgresVersion = await getPostgresVersion(1 as any);

    await logj({
      domain: "environment",
      level: "info",
      message: "Environment -- Retrieved Postgres Version",
      file: "app/api/environment/route.ts",
      line: 29,
      payload: {
        pg: {
          version: postgresVersion,
          major: postgresVersion.split(".")[0],
          raw: postgresVersion,
        },
      },

      meta: { built: { ...built, eventIndex: ++jei } },
    });

    //
    // 2. Vercel project + deployment
    //
    const vercelProject = {
      name: process.env.VERCEL_PROJECT_NAME ?? "unknown",
      TeamId: process.env.VERCEL_TEAM_ID ?? "unknown",
    };

    const vercelDeployment = {
      url: process.env.VERCEL_URL ?? "unknown",
      state: "active",
      meta: {
        githubCommitMessage: process.env.VERCEL_GIT_COMMIT_MESSAGE ?? "unknown",
      },
    };

    await logj({
      domain: "environment",
      level: "info",
      message: "Environment -- Retrieved Vercel Info",
      file: "app/api/environment/route.ts",
      line: 62,
      payload: { vercelDeployment },
      meta: { built: { ...built, eventIndex: ++jei } },
    });

    //
    // 3. GitHub info from your GithubEvent table
    //
    const latestCommit = await db8.orm.public.GithubEvent.where((githubEvent) =>
      githubEvent._type.eq("push"),
    )
      .orderBy((githubEvent) => githubEvent.createdAt.desc())
      .first();

    const latestWorkflow = await db8.orm.public.GithubEvent.where(
      (githubEvent) => githubEvent._type.eq("workflow_run"),
    )
      .orderBy((githubEvent) => githubEvent.createdAt.desc())
      .first();

    const github = {
      latestCommit: latestCommit
        ? {
            commit: {
              message: latestCommit.commitMessage,
              author: { name: latestCommit.actor },
            },
            sha: latestCommit.commitSha,
            url: latestCommit.url,
          }
        : null,

      latestWorkflow: latestWorkflow
        ? {
            name:
              latestWorkflow.title ?? latestWorkflow.jobName ?? "workflow_run",
            jobName: latestWorkflow.jobName,
            conclusion: latestWorkflow.conclusion,
            status: latestWorkflow.status,
            url: latestWorkflow.url,
          }
        : null,
    };
    await logj({
      domain: "environment",
      level: "info",
      message: "Environment -- Retrieved GithubInfo",
      file: "app/api/environment/route.ts",
      line: 108,
      payload: { github },
      meta: { built: { ...built, eventIndex: ++jei } },
    });
    //
    // 4. NEW: Full Neon project metadata (console API)
    //
    const neonApiKey = process.env.NEON_API_KEY!;
    const neonOrgId = process.env.NEON_ORG_ID!;

    const neonRes = await fetch(
      `https://console.neon.tech/api/v2/projects?org_id=${neonOrgId}`,
      {
        headers: {
          Authorization: `Bearer ${neonApiKey}`,
          Accept: "application/json",
        },
      },
    );

    const neonJson = await neonRes.json();
    const project = neonJson.projects?.[0];

    const neon = project
      ? {
          id: project.id,
          name: project.name,
          orgId: project.org_id,
          region: project.region_id,
          platform: project.platform_id,
          pgVersion: project.pg_version,
          autoscaling: {
            min: project.default_endpoint_settings.autoscaling_limit_min_cu,
            max: project.default_endpoint_settings.autoscaling_limit_max_cu,
            suspendTimeout:
              project.default_endpoint_settings.suspend_timeout_seconds,
          },
          networking: {
            proxyHost: project.proxy_host,
            blockPublicConnections: project.settings.block_public_connections,
            allowedIPs: project.settings.allowed_ips.ips,
          },
          storage: {
            branchLogicalSizeLimit: project.branch_logical_size_limit,
            branchLogicalSizeLimitBytes:
              project.branch_logical_size_limit_bytes,
            syntheticStorageSize: project.synthetic_storage_size,
            quotaResetAt: project.quota_reset_at,
          },
          maintenance: {
            weekdays: project.settings.maintenance_window.weekdays,
            start: project.settings.maintenance_window.start_time,
            end: project.settings.maintenance_window.end_time,
          },
          replication: {
            logicalReplication: project.settings.enable_logical_replication,
          },
          timestamps: {
            createdAt: project.created_at,
            updatedAt: project.updated_at,
            computeLastActiveAt: project.compute_last_active_at,
          },
          postgresVersion, // from Prisma
        }
      : { postgresVersion };
    console.log("env Neon Project Info:", neon);
    await logj({
      domain: "environment",
      level: "info",
      message: "Environment -- Retrieved Neon Info",
      file: "app/api/environment/route.ts",
      line: 179,
      payload: { neon },
      meta: { built: { ...built, eventIndex: ++jei } },
    });
    //
    // 5. Filter dependencies (Radix, TS, ESLint, etc.)
    //
    const IGNORE_PREFIXES = [
      "@radix-ui/",
      "@types/",
      "@typescript-eslint/",
      "eslint",
      "typescript",
      "ts-node",
      "vite",
      "vitest",
      "tailwindcss",
      "postcss",
      "autoprefixer",
    ];

    const IGNORE_ROOT_FIELDS = [
      "name",
      "version",
      "private",
      "packageManager",
      "type",
      "vercel-build-id",
      "overrides",
    ];

