import { logj } from "@/lib/log/logj";
import { buildUniversalContext } from "@/lib/log/build-universal-context";
import { getConfig } from "@/lib/runtime/config";
import { NextResponse } from "next/server";

export async function GET(req: Request) {
  const built = await buildUniversalContext(req, "fa-status");
  let jei = 0;
  const ident = await getConfig("flight-ID", "flight-ID");
  console.log("FINAL IDENT:", ident);
  await logj({
    domain: "jonathan",
    level: "info",
    message: "API FA status route accessed",
    file: "app/api/fa/status/route.ts",
    line: 15,
    payload: { ident },
    meta: { built: { ...built, eventIndex: ++jei } },
  });
  if (!ident) {
    return NextResponse.json({ error: "Missing ident" }, { status: 400 });
  }

  console.log("FA STATUS QUERY:", ident);

  const res = await fetch(
    `https://aeroapi.flightaware.com/aeroapi/flights/${ident}`,
    {
      headers: {
        "x-apikey": process.env.FLIGHTAWARE_API_KEY!,
      },
    },
  );

  console.log("FA STATUS RESPONSE:", res.status);

  if (!res.ok) {
    const err = await res.text();
    console.log("FA STATUS ERROR BODY:", err);
    return NextResponse.json(
      { error: "FlightAware error", status: res.status },
      { status: 500 },
    );
  }

  const data = await res.json();
  console.log("FA STATUS DATA:", data);
  type Flight = {
    scheduled_out?: string | null;
  };

  const today = new Date().toISOString().slice(0, 10);

  const todaysFlights = data.flights.filter((f: Flight) => {
    const sched = f.scheduled_out?.slice(0, 10);
    return sched === today;
  });

  let current: Flight | null = null;

  if (todaysFlights.length > 0) {
    const now = Date.now();

    const current = todaysFlights.reduce((closest: Flight, flight: Flight) => {
      const schedTime = new Date(flight.scheduled_out!).getTime();
      const closestTime = new Date(closest.scheduled_out!).getTime();

      return Math.abs(schedTime - now) < Math.abs(closestTime - now)
        ? flight
        : closest;
    });
  }

  console.log("CURRENT FLIGHT:", current);

  return NextResponse.json({ flight: current });
}

// app/api/logs/latest/route.ts
import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import { db8 } from "@/lib/db.prisma8";
import { or } from "@prisma/orm-postgres/orm-client";
import { timestampString } from "@/lib/timestampString";
import { logFromClient } from "@/app/actions/log";

export const dynamic = "force-dynamic";

export async function GET(req: NextRequest) {
  try {
    const since = req.nextUrl.searchParams.get("since");
    const search = req.nextUrl.searchParams.get("q") ?? "";

    let query = db8.orm.public.Log;

    if (since) {
      const cutoff = timestampString(new Date(since).toISOString());
      query = query.where((log) => log.createdAt.gt(cutoff));
    }

    if (search) {
      const pattern = `%${search}%`;
      query = query.where((log) =>
        or(
          log.message.like(pattern),
          log.level.like(pattern),
          log.file.like(pattern),
          log.requestId.like(pattern),
        ),
      );
    }

    const logs = await query
      .orderBy((log) => log.createdAt.desc())
      .limit(75)
      .all();

    return NextResponse.json({
      logs: logs.map(({ createdAt, ...log }) => ({
        ...log,
        created_at: new Date(`${createdAt}Z`).toISOString(),
      })),
    });
  } catch (err: any) {
    try {
      const result = await logFromClient(
        "logs",
        "Failed to fetch latest logs",
        "app/api/logs/latest/route.ts",
        45,
        { error: err.message },
      );
      console.log("logFromClient result:", result);
    } catch (err) {
      console.error("logFromClient failed:", err);
    }

    return NextResponse.json(
      { logs: [], error: "Internal Server Error" },
      { status: 500 },
    );
  }
}

