            </p>
            <p>
              <strong>Commit:</strong>{" "}
              {vercel.latestDeployment?.meta?.githubCommitMessage}
            </p>
          </div>
        </section>
      )}

      {/* NEON */}
      <section className="border rounded-lg p-4">
        <h2 className="text-xl color bg-red-600 font-semibold mb-2">
