// app/notes/NotesClient.tsx
"use client";

import { useEffect, useMemo, useState } from "react";
import toast from "react-hot-toast";
import { logj } from "@/lib/log/logj";

type Note = {
  id: string;
  title?: string | null;
  content?: string | null;
  followUpAt?: string | null;
  color?: string | null;
  createdAt: string;
  isArchived?: boolean;
  isCompleted?: boolean;
};

export default function NotesClient() {
  const [authorized, setAuthorized] = useState<boolean | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState("");
  const [editContent, setEditContent] = useState("");
  const [editNeedsFollowUp, setEditNeedsFollowUp] = useState(false);
  const [editFollowUpDate, setEditFollowUpDate] = useState("");
  const [editColor, setEditColor] = useState("");
  const [notes, setNotes] = useState<Note[] | null>(null);
  const [userId, setUserId] = useState<string | null>(null);
  const [followupsDueCount, setFollowupsDueCount] = useState<number>(0);
  const [showFollowupsOnly, setShowFollowupsOnly] = useState(false);

  const colorOptions = [
    { value: "", label: "None", className: "bg-gray-500" },
    { value: "red", label: "Red", className: "bg-red-500" },
    { value: "blue", label: "Blue", className: "bg-blue-500" },
    { value: "green", label: "Green", className: "bg-green-500" },
    { value: "yellow", label: "Yellow", className: "bg-yellow-500" },
    { value: "purple", label: "Purple", className: "bg-purple-500" },
    { value: "pink", label: "Pink", className: "bg-pink-500" },
    { value: "orange", label: "Orange", className: "bg-orange-500" },
  ];

  const isFollowupDueSoon = (note: Note) => {
    if (!note.followUpAt) return false;
    const now = new Date();
    const dueAt = new Date(note.followUpAt);
    const deadline = new Date(now);
    deadline.setDate(deadline.getDate() + 7);
    return dueAt >= now && dueAt <= deadline;
  };

  const refreshFollowupsDueCount = async () => {
    try {
      const dueRes = await fetch("/api/notes/due?days=7");
      if (dueRes.ok) {
        const dueData = await dueRes.json();
        setFollowupsDueCount(dueData.total ?? 0);
      } else {
        setFollowupsDueCount(0);
      }
    } catch (err) {
      setFollowupsDueCount(0);
      console.error("Error fetching follow-ups due count:", err);
    }
  };

  // Initial load: notes, user, auth, followups
  useEffect(() => {
    async function load() {
      const res = await fetch("/api/notes");
      const data = await res.json();

      if (res.status === 401) {
        toast.error(
          "🛑 Access denied — Authentication required for this mission.",
        );
        setAuthorized(false);
        return;
      }

      setAuthorized(true);
      setNotes(data.notes ?? []);
      setUserId(data.userId ?? "JK");

      await refreshFollowupsDueCount();
    }

    void load();
  }, []);

  useEffect(() => {
    void logj.info({
      domain: "notes",
      message: "Notes client loaded",
      file: "NotesClient.tsx",
      line: 55,
    });
  }, []);

  // Pure derived filtering: no setState, no effect needed
  const filteredNotes = useMemo(() => {
    if (!notes) return [];

    let currentNotes = notes;

    if (showFollowupsOnly) {
      currentNotes = currentNotes.filter(isFollowupDueSoon);
    }

    if (searchQuery.trim() === "") {
      return currentNotes;
    }

    const query = searchQuery.toLowerCase();

    return currentNotes.filter(
      (note) =>
        (note.title && note.title.toLowerCase().includes(query)) ||
        (note.content && note.content.toLowerCase().includes(query)),
    );
  }, [notes, showFollowupsOnly, searchQuery]);

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this note?")) return;

    try {
      const res = await fetch(`/api/notes?id=${id}`, {
        method: "DELETE",
      });

      if (res.ok) {
        setNotes(notes?.filter((note) => note.id !== id) ?? []);
        toast.success("Note deleted successfully");
        await refreshFollowupsDueCount();
      } else {
        toast.error("Failed to delete note");
      }
    } catch (error) {
      toast.error("Error deleting note");
    }
  };

  const handleEdit = (note: Note) => {
    setEditingId(note.id);
    setEditTitle(note.title || "");
    setEditContent(note.content || "");
    setEditNeedsFollowUp(!!note.followUpAt);
    setEditFollowUpDate(
      note.followUpAt
        ? new Date(note.followUpAt).toISOString().slice(0, 16)
        : "",
    );
    setEditColor(note.color || "");
  };

  const handleArchive = async (id: string) => {
    try {
      const res = await fetch("/api/notes", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          id,
          isArchived: true,
          isCompleted: true,
        }),
      });

      if (res.ok) {
        setNotes(notes?.filter((note) => note.id !== id) ?? []);
        toast.success("Note archived successfully");
        await refreshFollowupsDueCount();
      } else {
        toast.error("Failed to archive note");
      }
    } catch (error) {
      toast.error("Error archiving note");
    }
  };

  const handleSaveEdit = async () => {
    try {
      const res = await fetch("/api/notes", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          id: editingId,
          title: editTitle,
          content: editContent,
          followUpAt:
            editNeedsFollowUp && editFollowUpDate
              ? new Date(editFollowUpDate).toISOString()
              : null,
          color: editColor || null,
        }),
      });

      if (res.ok) {
        const data = await res.json();
        setNotes(
          notes?.map((note) => (note.id === editingId ? data.note : note)) ??
            [],
        );
        setEditingId(null);
        setEditTitle("");
        setEditContent("");
        setEditNeedsFollowUp(false);
        setEditFollowUpDate("");
        setEditColor("");
        toast.success("Note updated successfully");
        await refreshFollowupsDueCount();
      } else {
        toast.error("Failed to update note");
      }
    } catch (error) {
      toast.error("Error updating note");
    }
  };

  const handleCancelEdit = () => {
    setEditingId(null);
    setEditTitle("");
    setEditContent("");
    setEditNeedsFollowUp(false);
    setEditFollowUpDate("");
    setEditColor("");
  };

  if (authorized === null) {
    return <div className="p-6">Loading…</div>;
  }

  if (!authorized) {
    return <div className="p-6">You must be signed in to view notes.</div>;
  }

  return (
    <div className="p-6">
      <h1 className="text-xl font-bold mb-4">Your Notes</h1>

      {followupsDueCount > 0 && (
        <div className="mb-4 rounded-lg border border-orange-500/30 bg-orange-500/10 p-4 text-orange-100">
          <p className="font-semibold">
            You have {followupsDueCount} note
            {followupsDueCount === 1 ? "" : "s"} needing follow-up in the next 7
            days.
          </p>
          <p className="text-sm text-orange-100/80">
            Review or update them now to stay on top of your pending tasks.
          </p>
        </div>
      )}

      <div className="flex flex-col gap-2 mb-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex gap-2 flex-wrap">
          <button
            onClick={() => (window.location.href = "/notes/new")}
            className="px-4 py-2 rounded bg-blue-600 text-white hover:bg-blue-700 transition"
          >
            New Note
          </button>
          <button
            type="button"
            onClick={() => setShowFollowupsOnly((value) => !value)}
            className={`px-4 py-2 rounded transition ${showFollowupsOnly ? "bg-orange-600 text-white hover:bg-orange-700" : "bg-white/10 text-white hover:bg-white/20"}`}
          >
            {showFollowupsOnly
              ? "Show all notes"
              : `View follow-ups${
                  followupsDueCount > 0 ? ` (${followupsDueCount})` : ""
                }`}
          </button>
        </div>

        <input
          type="text"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder="Search notes..."
          className="flex-1 px-4 py-2 rounded bg-white/10 border border-white/20 text-white placeholder-white/60 outline-none focus:ring-2 focus:ring-blue-300"
        />
      </div>

      {filteredNotes.length === 0 && (
        <p>
          {searchQuery
            ? "No notes found matching your search."
            : "No notes yet."}
        </p>
      )}

      {filteredNotes.map((note) => (
        <div
          key={note.id}
          className={`mb-4 p-4 border rounded backdrop-blur-md ${
            note.color
              ? `bg-${note.color}-500/20 border-${note.color}-500/30`
              : "bg-white/10"
          }`}
        >
          {editingId === note.id ? (
            <div>
              <input
                type="text"
                value={editTitle}
                onChange={(e) => setEditTitle(e.target.value)}
                className="w-full mb-2 p-2 rounded bg-white/20 border border-white/30 text-white placeholder-white/60"
                placeholder="Note title..."
              />
              <textarea
                value={editContent}
                onChange={(e) => setEditContent(e.target.value)}
                className="w-full h-32 p-2 rounded bg-white/20 border border-white/30 text-white placeholder-white/60 resize-none"
                placeholder="Note content..."
              />

              <div className="mt-3 space-y-2">
                <div className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    id="editFollowUp"
                    checked={editNeedsFollowUp}
                    onChange={(e) => setEditNeedsFollowUp(e.target.checked)}
                    className="w-4 h-4 rounded border-white/30 bg-white/10 text-blue-600"
                  />
                  <label htmlFor="editFollowUp" className="text-white text-sm">
                    Needs follow-up
                  </label>
                </div>

                {editNeedsFollowUp && (
                  <input
                    type="datetime-local"
                    value={editFollowUpDate}
                    onChange={(e) => setEditFollowUpDate(e.target.value)}
                    className="w-full bg-white/20 border border-white/30 rounded p-2 text-white text-sm"
                  />
                )}
              </div>

              <div className="mt-3">
                <label className="block text-white text-sm mb-2">Color:</label>
                <div className="flex gap-2 flex-wrap">
                  {colorOptions.map((colorOption) => (
                    <button
                      key={colorOption.value}
                      type="button"
                      onClick={() => setEditColor(colorOption.value)}
                      className={`w-6 h-6 rounded-full border-2 ${colorOption.className} ${
                        editColor === colorOption.value
                          ? "border-white ring-2 ring-white/50"
                          : "border-white/30 hover:border-white/60"
                      }`}
                      title={colorOption.label}
                    />
                  ))}
                </div>
              </div>

              <div className="mt-2 flex gap-2">
                <button
                  onClick={handleSaveEdit}
                  className="px-3 py-1 rounded bg-green-600 text-white hover:bg-green-700 transition"
                >
                  Save
                </button>
                <button
                  onClick={handleCancelEdit}
                  className="px-3 py-1 rounded bg-gray-600 text-white hover:bg-gray-700 transition"
                >
                  Cancel
                </button>
              </div>
            </div>
          ) : (
            <div>
              <div className="flex justify-between items-start mb-2">
                <div className="flex items-center gap-2">
                  {note.color && (
                    <div
                      className={`w-4 h-4 rounded-full bg-${note.color}-500`}
                    />
                  )}
                  <h2 className="font-semibold text-lg">
                    {note.title || "Untitled"}
                  </h2>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={() => handleEdit(note)}
                    className="px-2 py-1 text-sm rounded bg-blue-600 text-white hover:bg-blue-700 transition"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => handleArchive(note.id)}
                    className="px-2 py-1 text-sm rounded bg-yellow-600 text-white hover:bg-yellow-700 transition"
                  >
                    Archive
                  </button>
                  <button
                    onClick={() => handleDelete(note.id)}
                    className="px-2 py-1 text-sm rounded bg-red-600 text-white hover:bg-red-700 transition"
                  >
                    Delete
                  </button>
                </div>
              </div>

              <p className="text-white/80 whitespace-pre-wrap">
                {note.content}
              </p>

              {note.followUpAt && (
                <div className="mt-2 p-2 bg-yellow-500/20 border border-yellow-500/30 rounded">
                  <p className="text-yellow-300 text-sm">
                    📅 Follow-up: {new Date(note.followUpAt).toLocaleString()}
                  </p>
                </div>
              )}

              <p className="text-xs text-white/60 mt-2">
                Created: {new Date(note.createdAt).toLocaleDateString()}
              </p>
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

"use client";

import { useState } from "react";

type Props = {
  authorized: boolean;
  userId: string;
};

export default function NewNoteClient({ authorized, userId }: Props) {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [needsFollowUp, setNeedsFollowUp] = useState(false);
  const [followUpDate, setFollowUpDate] = useState("");
  const [color, setColor] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  const colorOptions = [
    { value: "", label: "None", className: "bg-gray-500" },
    { value: "red", label: "Red", className: "bg-red-500" },
    { value: "blue", label: "Blue", className: "bg-blue-500" },
    { value: "green", label: "Green", className: "bg-green-500" },
    { value: "yellow", label: "Yellow", className: "bg-yellow-500" },
    { value: "purple", label: "Purple", className: "bg-purple-500" },
    { value: "pink", label: "Pink", className: "bg-pink-500" },
    { value: "orange", label: "Orange", className: "bg-orange-500" },
  ];
  const ctx = {
    requestId: crypto.randomUUID(),
  };

  async function handleSave() {
    setSaving(true);
    setError(null);
    setSuccess(false);

    try {
      const res = await fetch("/api/notes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title,
          content,
          followUpAt:
            needsFollowUp && followUpDate
              ? new Date(followUpDate).toISOString()
              : null,
          color: color || null,
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        setError(data.error || "Failed to save note");
      } else {
        setSuccess(true);
        setTitle("");
        setContent("");
        setNeedsFollowUp(false);
        setFollowUpDate("");
        setColor("");
        setTimeout(() => {
          window.location.href = "/notes";
        }, 1500);
      }
    } catch (err: any) {
      console.error("NOTES API ERROR", err);
      setError("Unexpected error");
    } finally {
      setSaving(false);
    }
  }

  if (!authorized) {
    return (
      <div className="bg-white/10 border border-white/20 rounded-xl p-6 max-w-xl mx-auto mt-12 text-center">
        <p className="text-white/80 text-lg">
          You must be signed in to create notes.
        </p>
      </div>
    );
  }

  return (
    <div className="bg-white/10 border border-white/20 rounded-xl p-6 max-w-xl mx-auto mt-12 shadow-xl backdrop-blur-md">
      <h2 className="text-2xl font-semibold mb-4">Create a New Note</h2>

      <input
        type="text"
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        placeholder="Note title (optional)..."
        className="w-full mb-4 bg-white/5 border border-white/20 rounded-lg p-4 text-white placeholder-white/60 outline-none focus:ring-2 focus:ring-blue-300"
      />

      <textarea
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Write your note..."
        className="w-full h-40 bg-white/5 border border-white/20 rounded-lg p-4 text-white placeholder-white/60 resize-none outline-none focus:ring-2 focus:ring-blue-300"
      />

      <div className="mt-4 space-y-3">
        <div className="flex items-center gap-3">
          <input
            type="checkbox"
            id="followUp"
            checked={needsFollowUp}
            onChange={(e) => setNeedsFollowUp(e.target.checked)}
            className="w-4 h-4 rounded border-white/30 bg-white/10 text-blue-600 focus:ring-blue-500"
          />
          <label htmlFor="followUp" className="text-white text-sm">
            Needs follow-up
          </label>
        </div>

        {needsFollowUp && (
          <div>
            <label
              htmlFor="followUpDate"
              className="block text-white text-sm mb-1"
            >
              Follow-up date:
            </label>
            <input
              type="datetime-local"
              id="followUpDate"
              value={followUpDate}
              onChange={(e) => setFollowUpDate(e.target.value)}
              className="w-full bg-white/5 border border-white/20 rounded-lg p-3 text-white outline-none focus:ring-2 focus:ring-blue-300"
            />
          </div>
        )}
      </div>

      <div className="mt-4">
        <label className="block text-white text-sm mb-2">Color:</label>
        <div className="flex gap-2 flex-wrap">
          {colorOptions.map((colorOption) => (
            <button
              key={colorOption.value}
              type="button"
              onClick={() => setColor(colorOption.value)}
              className={`w-8 h-8 rounded-full border-2 ${colorOption.className} ${
                color === colorOption.value
                  ? "border-white ring-2 ring-white/50"
                  : "border-white/30 hover:border-white/60"
              }`}
              title={colorOption.label}
            />
          ))}
        </div>
      </div>

      {error && <p className="text-red-300 mt-3 text-sm">{error}</p>}

      {success && (
        <p className="text-green-300 mt-3 text-sm">
          Note saved! Redirecting...
        </p>
      )}

      <button
        onClick={handleSave}
        disabled={saving || content.trim().length === 0}
        className="mt-4 bg-blue-500 hover:bg-blue-600 disabled:bg-blue-400 text-white font-semibold px-5 py-2 rounded-lg transition-colors"
      >
        {saving ? "Saving..." : "Save Note"}
      </button>

      <button
        onClick={() => (window.location.href = "/notes")}
        className="mt-4 ml-2 bg-gray-500 hover:bg-gray-600 text-white font-semibold px-5 py-2 rounded-lg transition-colors"
      >
        Cancel
      </button>
    </div>
  );
}

