import { db8 } from "./db.prisma8";

const API_KEY = process.env.TOMORROWIO_APIKEY!;

async function fetchWeatherForCity(city: string) {
  const url = `https://api.tomorrow.io/v4/weather/realtime?location=${encodeURIComponent(
    city,
  )}&units=imperial&apikey=${API_KEY}`;

  const res = await fetch(url);
  if (!res.ok) return null;

  const json = await res.json();
  const v = json?.data?.values;

  if (!v) return null;

  return {
    temperature: v.temperature,
    feelsLike: v.temperatureApparent,
    humidity: v.humidity,
    windSpeed: v.windSpeed,
    visibility: v.visibility,
    weatherCode: v.weatherCode,
    fetchedAt: new Date(),
  };
}

export async function buildSendWeatherEmail() {
  // 1. Get the most recent snapshot
  const snapshot = await db8.orm.public.TravelSnapshot.include("travelSegments")
    .orderBy((snapshot) => snapshot.receivedAt.desc())
    .first();

  if (!snapshot) {
    return {
      subject: "Your Upcoming Trip",
      text: "No upcoming trip found.",
      html: `<p>No upcoming trip found.</p>`,
    };
  }

  const segments = snapshot.travelSegments
    .sort((a: any, b: any) => a.departureTime - b.departureTime)
    .sort((a: any, b: any) => a.departureTime.localeCompare(b.departureTime));

  if (segments.length === 0) {
    return {
      subject: "Your Upcoming Trip",
      text: "No segments found for this trip.",
      html: `<p>No segments found for this trip.</p>`,
    };
  }

  // 2. Fetch weather for each arrival city
  const weatherByCity: Record<string, any> = {};

  for (const seg of segments) {
    weatherByCity[seg.arrivalCity] = await fetchWeatherForCity(seg.arrivalCity);
  }

  const [outbound, inbound] = segments;

  const outWeather = weatherByCity[outbound!.arrivalCity];
  const inWeather = weatherByCity[inbound!.arrivalCity];

  const formatTemp = (t: number | null | undefined) =>
    t != null ? `${t}°F` : "—";

  // 3. Build HTML
  const html = `
  <div style="font-family: system-ui, sans-serif; padding: 20px; color: #0a2540;">
    <h1 style="margin-bottom: 10px;">Your Upcoming Trip</h1>

    <p style="color: #555; margin-top: 0;">
      Automatically generated by your Travel Dashboard
    </p>

    <hr style="margin: 20px 0; border: none; border-top: 1px solid #ddd;" />

    <!-- OUTBOUND -->
    <h2 style="margin-bottom: 5px;">Outbound Flight</h2>
    <p style="margin: 0 0 10px 0;">
      <strong>${outbound!.departureCity} → ${outbound!.arrivalCity}</strong><br/>
      ${outbound!.date}<br/>
      ${outbound!.departureTime} → ${outbound!.arrivalTime}<br/>
      Seats: ${outbound!.seats.join(", ")}
    </p>

    <h3 style="margin: 10px 0 5px;">Weather on Arrival</h3>
    ${
      outWeather
        ? `
        <div style="padding: 10px; background: #f0f7ff; border-radius: 8px;">
          <div><strong>Temperature:</strong> ${formatTemp(outWeather.temperature)}</div>
          <div><strong>Feels Like:</strong> ${formatTemp(outWeather.feelsLike)}</div>
          <div><strong>Humidity:</strong> ${outWeather.humidity ?? "—"}%</div>
          <div><strong>Wind:</strong> ${outWeather.windSpeed ?? "—"} mph</div>
          <div><strong>Visibility:</strong> ${outWeather.visibility ?? "—"} mi</div>
          <div style="font-size: 12px; color: #666; margin-top: 5px;">
            Updated: ${outWeather.fetchedAt.toLocaleString()}
          </div>
        </div>
      `
        : `<p>No weather data available.</p>`
    }

    <hr style="margin: 20px 0; border: none; border-top: 1px solid #ddd;" />

    <!-- RETURN -->
    <h2 style="margin-bottom: 5px;">Return Flight</h2>
    <p style="margin: 0 0 10px 0;">
      <strong>${inbound!.departureCity} → ${inbound!.arrivalCity}</strong><br/>
      ${inbound!.date}<br/>
      ${inbound!.departureTime} → ${inbound!.arrivalTime}<br/>
      Seats: ${inbound!.seats.join(", ")}
    </p>

    <h3 style="margin: 10px 0 5px;">Weather on Return</h3>
    ${
      inWeather
        ? `
        <div style="padding: 10px; background: #f0f7ff; border-radius: 8px;">
          <div><strong>Temperature:</strong> ${formatTemp(inWeather.temperature)}</div>
          <div><strong>Feels Like:</strong> ${formatTemp(inWeather.feelsLike)}</div>
          <div><strong>Humidity:</strong> ${inWeather.humidity ?? "—"}%</div>
          <div><strong>Wind:</strong> ${inWeather.windSpeed ?? "—"} mph</div>
          <div><strong>Visibility:</strong> ${inWeather.visibility ?? "—"} mi</div>
          <div style="font-size: 12px; color: #666; margin-top: 5px;">
            Updated: ${inWeather.fetchedAt.toLocaleString()}
          </div>
        </div>
      `
        : `<p>No weather data available.</p>`
    }

    <hr style="margin: 20px 0; border: none; border-top: 1px solid #ddd;" />

    <p style="font-size: 12px; color: #666;">
      Travel Weather Bot • ${new Date().toLocaleString()}
    </p>
  </div>
  `;

  return {
    subject: `Your Upcoming Trip: ${outbound!.departureCity} → ${outbound!.arrivalCity}`,
    text: `Your upcoming trip details are ready.`,
    html,
  };
}

import { neon } from "@neondatabase/serverless";
import { logj } from "@/lib/log/logj";
import { staticUniversalContext } from "@/lib/log/buildj";
import { db8 } from "@/lib/db.prisma8";
import { timestampString } from "@/lib/timestampString";
import { createId } from "@paralleldrive/cuid2";

const sql = neon(process.env.DATABASE_URL!);

function atLocalMidnight(d: Date) {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

type TableStatRow = {
  table_name: string;
  total_bytes: number | string;
  table_bytes: number | string;
  index_bytes: number | string;
  toast_bytes: number | string;
};

export async function runDbTableStats(ctx: {
  requestId?: string;
  route?: string;
  userId?: string;
}) {
  const start = Date.now();

  // JavaScript Date for normal application/logging use
  const snapshotDate = atLocalMidnight(new Date());

  // Prisma 8 DbTableStats.snapshotDate is TimestampString(3)
  const snapshotDate8 = timestampString(snapshotDate.toISOString());

  const built = staticUniversalContext("runstats");
  let jei = 1;

  await logj({
    domain: "jonathan",
    level: "info",
    message: "dbTables cron started",
    file: "lib/cron/runDbTableStats.ts",
    line: 34,
    payload: {
      date: snapshotDate.toISOString(),
    },
    meta: { built: { ...built, eventIndex: ++jei } },
  });

  // Fetch table list
  const stats = (await sql`
    SELECT
      c.relname AS table_name,
      pg_total_relation_size(c.oid) AS total_bytes,
      pg_relation_size(c.oid) AS table_bytes,
      pg_indexes_size(c.oid) AS index_bytes,
      pg_total_relation_size(c.oid)
        - pg_relation_size(c.oid)
        - pg_indexes_size(c.oid) AS toast_bytes
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE c.relkind = 'r'
      AND n.nspname = 'public';
  `) as TableStatRow[];

  let tablesProcessed = 0;

  for (const row of stats) {
    const tableName = row.table_name;

    await logj({
      domain: "jonathan",
      level: "info",
      message: `dbTables preparing to count rows for table ${tableName}`,
      file: "lib/cron/runDbTableStats.ts",
      line: 67,
      payload: {
        name: tableName,
      },
      meta: { built: { ...built, eventIndex: ++jei } },
    });

    try {
      // COUNT rows
      const count =
        (
          await sql`
            SELECT COUNT(*)::int AS count
            FROM ${sql.unsafe(`public."${tableName.replace(/"/g, '""')}"`)}
          `
        )[0]?.count ?? 0;

      await logj({
        domain: "jonathan",
        level: "info",
        message: `dbTables update started for table ${tableName} with ${count} rows`,
        file: "lib/cron/runDbTableStats.ts",
        line: 93,
        payload: {
          name: tableName,
          count,
        },
        meta: { built: { ...built, eventIndex: ++jei } },
      });

      // Find today's existing snapshot for this table
      const existing = await db8.orm.public.DbTableStats.where((stat) =>
        stat.tableName.eq(row.table_name),
      )
        .where((stat) => stat.snapshotDate.eq(snapshotDate8))
        .first();

      const values = {
        tableName: row.table_name,
        snapshotDate: snapshotDate8,
        rowEstimate: count,
        totalBytes: BigInt(row.total_bytes),
        tableBytes: BigInt(row.table_bytes),
        indexBytes: BigInt(row.index_bytes),
        toastBytes: BigInt(row.toast_bytes),
      };

      if (existing) {
        await db8.orm.public.DbTableStats.where({ id: existing.id }).update(
          values,
        );
      } else {
        await db8.orm.public.DbTableStats.create({
          id: createId(),
          ...values,
        });
      }

      tablesProcessed++;
    } catch (err: any) {
      await logj({
        domain: "jonathan",
        level: "error",
        message: `dbTables error for table ${tableName}`,
        file: "lib/cron/runDbTableStats.ts",
        line: 132,
        payload: {
          error: String(err),
          name: tableName,
        },
        meta: { built: { ...built, eventIndex: ++jei } },
      });

      // Continue to next table instead of aborting cron
      continue;
    }
  }

  await logj({
    domain: "jonathan",
    level: "info",
    message: "dbTables cron completed",
    file: "lib/cron/runDbTableStats.ts",
    line: 148,
    payload: {
      tables: tablesProcessed,
      durationMs: Date.now() - start,
    },
    meta: { built: { ...built, eventIndex: ++jei } },
  });
}

