export type SafeResult<T> =
  { ok: true; data: T } | { ok: false; error: unknown };

export async function safe<T>(fn: () => Promise<T>): Promise<SafeResult<T>> {
  try {
    const data = await fn();
    return { ok: true, data };
  } catch (error) {
    console.error("Dashboard fetch error:", error);
    return { ok: false, error };
  }
}

