export function getSha(payload: any): string | null {
  if (!payload) return null;

  // Push events
  if (payload.head_commit?.id) return payload.head_commit.id;

  // Workflow run
  if (payload.workflow_run?.head_sha) return payload.workflow_run.head_sha;

  // Workflow job
  if (payload.workflow_job?.head_sha) return payload.workflow_job.head_sha;

  // Check suite
  if (payload.check_suite?.head_sha) return payload.check_suite.head_sha;

  // Check run
  if (payload.check_run?.head_sha) return payload.check_run.head_sha;

  // Pull request
  if (payload.pull_request?.head?.sha) return payload.pull_request.head.sha;

  return null;
}

export function transformGitHubRun(payload: any) {
  const wr = payload.workflow_run;
  if (!wr) return null;

  return {
    id: wr.id,
    displayTitle: wr.display_title ?? "no title",
    // Workflow metadata
    name: wr.name,
    repo: payload.repository?.full_name ?? null,

    // Status + result
    status: wr.status ?? null,
    conclusion: wr.conclusion ?? null,

    // Event context
    event: payload.action ?? "workflow_run",
    actor: wr.actor?.login ?? payload.sender?.login ?? null,

    // Commit info
    commitMessage: wr.head_commit?.message ?? null,
    commitSha: wr.head_sha ?? null,

    // Link
    url: wr.html_url ?? null,

    // Timestamps
