import { describe, it, expect, vi, beforeEach } from "vitest";

vi.mock("@/lib/runtime/config", () => ({
  getConfig: vi.fn().mockReturnValue("0"), // debug off
}));

vi.mock("@/lib/db.prisma8", () => ({
